import fs from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';
import assert from 'node:assert/strict';
import {fileURLToPath} from 'node:url';
import {parseHTML} from './poverkadoma-qa-dom.mjs';
const base=path.dirname(fileURLToPath(import.meta.url)),fragment=fs.readFileSync(path.join(base,'poverkadoma-verifier-app-preview.html'),'utf8'),code=fragment.match(/<script>\s*([\s\S]*?)\s*<\/script>/)[1];
const checks=[];const pass=(name,fn)=>{if(process.env.PD_QA_TRACE)console.log(name);fn();checks.push(name);};
function setup(state,{echo=false,clock=false,reduced=false}={}){const {window,document,Event}=parseHTML('<html><body>'+fragment+'</body></html>');const saves=[];const hostEcho=value=>{const event=new Event('openai:set_globals');event.detail={globals:{widgetState:JSON.parse(JSON.stringify(value))}};window.dispatchEvent(event);};window.openai={widgetState:state,setWidgetState:s=>{saves.push(JSON.parse(JSON.stringify(s)));if(echo)hostEcho(s);return Promise.resolve();}};window.setTimeout=()=>1;window.clearTimeout=()=>{};window.matchMedia=()=>({matches:reduced});let stamp=0,frameSequence=0;const frames=new Map();if(clock){window.performance={now:()=>stamp};window.requestAnimationFrame=fn=>{frames.set(++frameSequence,fn);return frameSequence;};window.cancelAnimationFrame=id=>frames.delete(id);}const draw=()=>{const callbacks=[...frames.values()];frames.clear();callbacks.forEach(fn=>fn(stamp));};const advance=ms=>{for(let left=ms;left>0;){const delta=Math.min(100,left);stamp+=delta;left-=delta;draw();}};
  const proto=Object.getPrototypeOf(document.createElement('select'));Object.defineProperty(proto,'value',{configurable:true,get(){return this.querySelector('option[selected]')?.getAttribute('value')??this.querySelector('option')?.getAttribute('value')??'';},set(v){this.querySelectorAll('option').forEach(n=>n.toggleAttribute('selected',n.getAttribute('value')===String(v)));}});
  class DemoDate extends Date{constructor(...a){super(...(a.length?a:[2026,9,30,10,30]));}}
  new vm.Script(code).runInNewContext({window,document,console,Date:DemoDate,setTimeout:()=>1,clearTimeout:()=>{},URL,Blob});
  if(clock)draw();
  const app=document.querySelector('.phone'),core=app.verifierApp;
  const fire=(selector,type='click')=>{const n=typeof selector==='string'?document.querySelector(selector):selector;assert.ok(n,'Missing '+selector);if(type==='click'){assert.ok(!n.closest('[hidden]'),'Hidden control '+selector);assert.ok(!n.disabled,'Disabled control '+selector);}n.dispatchEvent(new Event(type,{bubbles:true}));return n;};
  const change=(selector,value,type='change')=>{const n=document.querySelector(selector);assert.ok(n,'Missing '+selector);if(n.type==='checkbox')n.checked=value;else n.value=value;fire(n,type);return n;};
  const clickText=(value,container=document.querySelector('#verifier-screen'))=>{const n=[...container.querySelectorAll('button,a')].find(n=>!n.closest('[hidden]')&&n.textContent.trim()===value);assert.ok(n,'Missing control '+value);return fire(n);};
  const picker=(id,value)=>{const input=document.getElementById(id);assert.ok(input?.hidden,'Native source must be hidden: '+id);fire('[data-picker-for="'+id+'"]');const option=[...document.querySelectorAll('#verifier-modal [data-picker-value]')].find(n=>n.dataset.pickerValue===String(value));assert.ok(option,'Missing picker option '+id+'='+value);fire(option);return document.getElementById(id);};
  const datePicker=(id,value)=>{assert.ok(document.getElementById(id)?.hidden,'Native date source must be hidden: '+id);fire('[data-picker-for="'+id+'"]');assert.ok(document.querySelector('#verifier-modal .v-calendar'),'Missing custom calendar');fire('[data-calendar-date="'+value+'"]');return document.getElementById(id);};
  const visibleHeader=()=>[...app.querySelectorAll('header.topbar')].find(n=>!n.closest('[hidden]'));
  const tapTop=label=>{const target=[...visibleHeader().querySelectorAll('button')].find(n=>n.getAttribute('aria-label')===label&&!n.closest('[hidden]'));assert.ok(target,'Missing visible top action '+label);return fire(target);};
  const byAccessibleName=(name,container=document.querySelector('#verifier-screen'))=>{const n=[...container.querySelectorAll('button,a')].find(n=>!n.closest('[hidden]')&&(n.getAttribute('aria-label')===name||n.textContent.trim()===name));assert.ok(n,'Missing accessible action '+name);return fire(n);};
  return {window,document,app,core,saves,fire,change,clickText,picker,datePicker,hostEcho,visibleHeader,tapTop,byAccessibleName,advance};}
function destinationFromRoot(s,route){
  let taps=0;const fire=n=>{taps++;s.fire(n);};
  const named=(...labels)=>{const n=[...s.document.querySelectorAll('#verifier-screen button,#verifier-screen a')].find(n=>!n.closest('[hidden]')&&labels.some(label=>n.getAttribute('aria-label')===label||n.textContent.trim()===label));assert.ok(n,'Missing direct destination '+route);fire(n);};
  if(['requests','acts','tools'].includes(route))fire('[data-nav="'+route+'"]');
  else if(['settings','notifications'].includes(route))fire('[data-nav="'+route+'"]');
  else if(route==='account'){fire('[data-nav="settings"]');fire('.v-profile-summary');}
  else if(['messages','feedback'].includes(route)){fire('[data-nav="notifications"]');named(route==='messages'?'Сообщения':'Поддержка');}
  else if(['upload','history','statistics'].includes(route)){fire('[data-nav="acts"]');named({upload:'Выгрузить всё',history:'История',statistics:'Статистика'}[route]);}
  else{fire('[data-nav="tools"]');const tile=s.document.querySelector('[data-tools-destination="'+route+'"]');if(tile)fire(tile);else named(...({equipment:['Приборы'],tags:['Бирки','Идентификационные бирки'],storage:['Условия хранения','Хранение'],nepton:['НЕПТОН','Подключение к НЕПТОН'],guide:['Справочник СИ','Справочник'],arshin:['АРШИН','Поиск в АРШИН'],documents:['Документы','Документы СМК','Документы организации']}[route]||[route]));}
  return taps;
}
function destinationFromSettings(s,route){assert.equal(s.core.getRoute().route,'settings');s.tapTop('Разделы');s.fire('[data-section-destination="'+route+'"]');return 2;}
pass('History cycles 10/50/100, paginates without duplicates, and keeps preferences after reload',()=>{
  const s=setup();s.core.navigate('history');const ids=()=>[...s.document.querySelectorAll('.v-history-card')].map(n=>n.dataset.historyId);
  assert.equal(ids().length,10);const first=ids();s.fire('.v-history-pager button:last-child');assert.equal(ids().length,10);assert.ok(ids().every(id=>!first.includes(id)));
  for(const size of [50,100,10]){s.fire('.v-history-limit');assert.equal(ids().length,size);assert.equal(ids()[0],first[0]);assert.equal(s.document.querySelector('.v-history-limit').textContent,String(size));}
  s.fire('.v-history-limit');const r=setup(s.core.persist());r.core.navigate('history');assert.equal(r.document.querySelectorAll('.v-history-card').length,50);assert.equal(r.core.modules.acts.getState().acts.length,9);
});
