pass('The main prototype exposes five timer styles outside the phone,uses a softer single wave and keeps the normal button48px',()=>{const s=setup(),select=s.document.querySelector('#request-timer-style');assert.equal(select.closest('.phone'),null);assert.equal(select.querySelectorAll('option').length,5);assert.equal(s.app.dataset.requestTimerStyle,'wave');for(const style of ['window','plain-tab','seal','meeting','wave']){s.change('#request-timer-style',style);assert.equal(s.app.dataset.requestTimerStyle,style);assert.ok(s.app.querySelector('#requests .request-timer-panel'));if(['seal','meeting'].includes(style)){const resumed=setup(s.core.snapshot());assert.equal(resumed.app.dataset.requestTimerStyle,style);assert.equal(resumed.app.verifierTimerDemo.getState().style,style);}}const css=fs.readFileSync(path.join(base,'poverkadoma-verifier-timer-preview.css'),'utf8');assert.match(css,/\.phone \.request-action\.primary\.agreement-action\.has-timer-preview\s*\{[^}]*height:48px;[^}]*background:var\(--blue-fill\)/);assert.ok(!/timer.*meter|timer.*track/.test(css));const polygon=s.app.style.getPropertyValue('--request-timer-wave');assert.ok(polygon.startsWith('polygon('));const points=[...polygon.matchAll(/([\d.]+)px ([\d.]+)%/g)].map(m=>[Number(m[1]),Number(m[2])]);assert.ok(points.length>90);let maximumSlope=0;for(let i=1;i<points.length;i++){const dy=(points[i][1]-points[i-1][1])*.48;if(dy)maximumSlope=Math.max(maximumSlope,Math.abs((points[i][0]-points[i-1][0])/dy));}assert.ok(maximumSlope<.4,'New wave must be gentler than the earlier slope1.31');});
pass('Shared timer loops30 to minus10,changes colors,and synchronizes cards and request details without modifying data',()=>{const s=setup(undefined,{clock:true}),demo=s.app.verifierTimerDemo,source=JSON.stringify(s.core.api.getRequests()),drafts=JSON.stringify(s.core.api.getRequestState().privateContent.requestDrafts);assert.equal(demo.getDisplayMinutes(),30);assert.equal(demo.getVisualColor().join(','),'0,132,193');s.advance(15000);assert.equal(demo.getDisplayMinutes(),15);assert.equal(demo.getVisualColor().join(','),'255,178,28');s.advance(10000);assert.equal(demo.getDisplayMinutes(),5);assert.equal(demo.getVisualColor().join(','),'217,97,97');s.core.navigate('request',{id:'sample-appointed'});const deadline=s.document.querySelector('#request-deadline');assert.equal(deadline.hidden,false);assert.equal(deadline.dataset.timerPreviewMinutes,'5');s.advance(5000);assert.equal(demo.getDisplayMinutes(),0);assert.ok(deadline.textContent.includes('истекло'));s.advance(5000);assert.equal(demo.getDisplayMinutes(),-5);assert.ok(deadline.textContent.includes('просрочено на 5 мин'));assert.equal(deadline.dataset.timerPreviewMinutes,'-5');assert.ok([...s.app.querySelectorAll('#requests .has-timer-preview')].every(n=>n.dataset.timerPreviewMinutes==='-5'));assert.ok([...s.app.querySelectorAll('#requests .request-timer-caption')].every(n=>n.textContent==='Просрочено'));s.advance(5000);assert.equal(demo.getDisplayMinutes(),-10);s.advance(1500);assert.equal(demo.getDisplayMinutes(),-10);s.advance(500);assert.equal(demo.getDisplayMinutes(),30);assert.equal(deadline.dataset.timerPreviewMinutes,'30');assert.equal(s.saves.length,1,'Only navigation saves;animation frames do not');assert.equal(JSON.stringify(s.core.api.getRequests()),source);assert.equal(JSON.stringify(s.core.api.getRequestState().privateContent.requestDrafts),drafts);});
pass('Pause,manual time,restart,style switches and restored state work without detaching source actions',()=>{const s=setup(undefined,{clock:true,echo:true}),demo=s.app.verifierTimerDemo;s.advance(8000);s.fire('#request-timer-play');assert.equal(demo.getState().playing,false);const held=demo.getDisplayMinutes();s.advance(10000);assert.equal(demo.getDisplayMinutes(),held);s.change('#request-timer-style','plain-tab');s.change('#request-timer-minutes','0','input');assert.ok([...s.app.querySelectorAll('#requests .request-timer-value')].every(n=>n.textContent==='истёк'));assert.ok([...s.app.querySelectorAll('#requests .has-timer-preview')].every(n=>n.getAttribute('aria-label').includes('срок истёк')));const heldSnapshot=s.core.snapshot();s.fire('#request-timer-restart');assert.equal(demo.getDisplayMinutes(),30);s.advance(10000);assert.equal(demo.getDisplayMinutes(),20);s.fire('[data-request-id="000394"] .request-action:not(.request-call)');assert.equal(s.core.getRoute().route,'requests');assert.equal(s.document.querySelector('#verifier-modal').hidden,false);const restored=setup(heldSnapshot,{clock:true});assert.equal(restored.app.dataset.requestTimerStyle,'plain-tab');assert.equal(restored.app.verifierTimerDemo.getState().playing,false);assert.equal(restored.app.verifierTimerDemo.getDisplayMinutes(),0);});
