pass('External label saturation changes all status families and survives routes,packed restores and host echoes',()=>{const s=setup(undefined,{echo:true}),select=s.document.querySelector('#label-appearance');assert.ok(select);assert.equal(select.closest('.phone'),null);assert.equal(s.app.dataset.labelAppearance,'soft');s.change('#label-appearance','solid');assert.equal(s.app.dataset.labelAppearance,'solid');for(const route of ['requests','acts','tools','request']){s.core.navigate(route,route==='request'?{id:'000394'}:{});assert.equal(s.app.dataset.labelAppearance,'solid');}const snapshot=s.core.persist(),restored=setup(snapshot);assert.equal(restored.app.dataset.labelAppearance,'solid');assert.equal(restored.document.querySelector('#label-appearance').value,'solid');restored.change('#label-appearance','soft');assert.equal(restored.app.dataset.labelAppearance,'soft');const css=fs.readFileSync(path.join(base,'poverkadoma-verifier-labels.css'),'utf8');for(const selector of ['.request-state','.v-status','.v-tool-status','.detail-status-badge'])assert.ok(css.includes('[data-label-appearance="solid"] '+selector));assert.match(css,/background:var\(--label-tone\); color:#fff/);assert.match(css,/\.detail-status-badge \.status-dot[^}]*display:none/);const appCss=fs.readFileSync(path.join(base,'poverkadoma-verifier-app.css'),'utf8'),detailCss=fs.readFileSync(path.join(base,'poverkadoma-request-detail.css'),'utf8');assert.match(appCss,/\.v-danger \{[^}]*color: #fff/);assert.match(appCss,/data-v-theme="dark"[^\n]*\.v-danger[^}]*color: #fff/);assert.match(detailCss,/detail-cancel \{[^}]*color: #fff/);});
