pass('Request filters normalize retired services and preserve mixed localities and assignment scope',()=>{
  const s=setup(),base=s.core.api.getRequestState();base.modelContent.cityScenario='mixed';base.privateContent.requestDrafts['000394']={service:'Замена ИПУ',baseService:'Поверка газового счётчика',note:'Сохранённое примечание'};base.privateContent.requestFilters={service:'Замена ИПУ'};s.core.api.restoreRequestState(base);
  s.fire('#filter-toggle');s.picker('filter-city','Тольятти');s.picker('filter-service','Поверка ИПУ');assert.equal(s.document.querySelector('#filter-apply').textContent,'Показать · 4');s.fire('#filter-apply');assert.equal(s.document.querySelectorAll('#requests .request').length,4);const cleaned=s.core.api.getRequestState();assert.equal(cleaned.privateContent.requestDrafts['000394'].service,undefined);assert.equal(cleaned.privateContent.requestDrafts['000394'].baseService,undefined);assert.equal(cleaned.privateContent.requestDrafts['000394'].note,'Сохранённое примечание');const restored=setup(s.core.snapshot());restored.fire('#filter-toggle');assert.deepEqual([...restored.document.querySelectorAll('#filter-service option')].map(n=>n.textContent),['Все услуги','Поверка ИПУ']);assert.ok(!restored.document.querySelector('#request-sample').textContent.includes('Замена ИПУ'));restored.fire('#filter-close');restored.fire('#requests .request .request-entry');assert.equal(restored.document.querySelector('#detail-service').textContent,'Поверка ИПУ');
  s.fire('#filter-toggle');s.fire('#filter-reset');s.picker('filter-scope','available');s.fire('#filter-apply');assert.equal(s.document.querySelectorAll('#requests .request').length,8);
  s.fire('#filter-toggle');s.fire('[data-status="new"]');s.fire('#filter-apply');const reloaded=setup(s.core.snapshot());assert.equal(reloaded.document.querySelectorAll('#requests .request').length,8);reloaded.core.resetDemoData();assert.equal(reloaded.document.querySelector('#filter-summary').hidden,true);assert.equal(reloaded.core.api.getRequestState().privateContent.requestDrafts['000394'],undefined);
  const legacy=s.core.snapshot();legacy.privateContent.verifier.route='request';legacy.privateContent.verifier.params={id:'sample-replacement'};legacy.privateContent.requestDrafts['sample-replacement']={service:'Замена ИПУ',address:'Сохранённая улица, 12',comment:'Сохранённый комментарий'};legacy.privateContent.requestDrafts['sample-agreed']={address:'Другой пример, 24',comment:'Другой комментарий'};const reopened=setup(legacy);assert.equal(reopened.core.getRoute().params.id,'sample-replacement');assert.equal(reopened.document.querySelector('#detail-service').textContent,'Поверка ИПУ');assert.equal(reopened.document.querySelector('#detail-address').textContent,'Сохранённая улица, 12');reopened.fire('[data-note-toggle="comment"]');assert.equal(reopened.document.querySelector('#detail-comment').value,'Сохранённый комментарий');const reopenedAgain=setup(reopened.core.snapshot());assert.equal(reopenedAgain.document.querySelector('#detail-address').textContent,'Сохранённая улица, 12');assert.equal(reopenedAgain.core.api.getRequestState().privateContent.requestDrafts['sample-replacement'].comment,'Сохранённый комментарий');
});
